  [459699] = { "Ottieni l'abilità Fear Ward:\n\n$I1\nProtegge il bersaglio amico dalla paura. Il prossimo effetto di paura usato contro il bersaglio fallisce, consumando la protezione. Dura $D1.", nil, 0x3eb91ccc, nil, "um" },
  [459702] = { "Ottieni l'abilità ⟦Desperate Prayer=Preghiera Disperata⟧:\n\n$I1\nCura istantaneamente l'incantatore di $N1.", nil, 0xcde4c4fb, nil, "um" },
  [459703] = { "Ottieni l'abilità Retroazione:\n\n$I1\nIl Sacerdote si circonda di energia antimagica. Ogni incantesimo lanciato con successo contro il Sacerdote brucia $N1 mana dell'attaccante, infliggendo $N2 danni da ombra per ogni punto di mana bruciato. Dura $D1.", nil, 0x44156cb3, nil, "um" },
  [459705] = { "Ottieni l'abilità Schegge Stellari:\n\n$I1\nFrammenti stellari cadono sulla testa del bersaglio nemico, infliggendo $N1 danni da arcano in $D1.", nil, 0x4a984884, nil, "um" },
  [459709] = { "Ottieni l'abilità Guardia dell'Ombra:\n\n$I1\nL'incantatore è circondato dalle ombre. Quando un incantesimo o un attacco in mischia o a distanza colpisce l'incantatore, l'attaccante subisce $N1 danni da ombra. Gli attaccanti possono subire danni solo una volta ogni pochi secondi. Questi danni non generano minaccia. $N2 cariche. Dura $D1.", nil, 0x3902ce5c, nil, "um" },
  [459710] = { "Ottieni l'abilità ⟦Hex of Weakness=Maleficio di Debolezza⟧:\n\n$I1\nIndebolisce il bersaglio nemico, riducendo la potenza d'attacco in mischia di $N1 e l'efficacia delle cure ricevute del $N2%. Dura $D1.", nil, 0x8b3300f1, nil, "um" },
  [459713] = { "Ottieni l'abilità Piaga Divoratrice:\n\n$I1\nAffligge il bersaglio con una malattia che infligge $N1 danni da ombra in $D1. I danni causati da Piaga Divoratrice curano l'incantatore.", nil, 0x36ead55a, nil, "um" },
  [459714] = { "Ottieni l'abilità Tocco della Debolezza:\n\n$I1\nIl prossimo attacco in mischia contro l'incantatore infligge $N1 danni da ombra e riduce la potenza d'attacco in mischia dell'attaccante di $N2 per $D1.", nil, 0xc804a15e, nil, "um" },
  [459736] = { "Aumenta la Tempra di $N1 per $D1 e infonde ubriachezza molesta!", "Tempra aumentata di $N1.", 0xfaf19c38, 0x4e3b423b, "uu" },
